import { fileURLToPath } from "node:url";

// Kratos's own files, relative to this module. Kept in one module at the top of src/ so the paths
// hold from src/, from tsc's dist/, and from the single binary's bundle (dist/kratos.mjs, 3u3),
// whose virtual filesystem has them at the same places.

/** The built UI (apps/web/dist). */
export const WEB_DIST = fileURLToPath(new URL("../../web/dist/", import.meta.url));

/** SQL migrations generated by drizzle-kit (apps/cli/drizzle). */
export const MIGRATIONS = fileURLToPath(new URL("../drizzle", import.meta.url));
